func workspacePermissionAssignmentOutputFromWire(w *workspacePermissionAssignmentOutputWire) *WorkspacePermissionAssignmentOutput {
	if w == nil {
		return nil
	}
	return &WorkspacePermissionAssignmentOutput{
		Principal:   principalOutputFromWire(w.Principal),
		Permissions: w.Permissions,
		Error:       w.Error,
	}
}

func convertSlice[T, W any](s []T, conv func(*T) *W) []W {
	if s == nil {
		return nil
	}
	out := make([]W, len(s))
	for i := range s {
		out[i] = *conv(&s[i])
	}
	return out
}
